import{URL,KEY,request,saveSession}from'./api.js';
const token=location.hash.slice(1),form=document.getElementById('activationForm'),status=document.getElementById('status'),button=document.getElementById('activate');
if(!/^[A-Za-z0-9_-]{43}$/.test(token)){form.hidden=true;status.textContent='Abra o link completo de primeiro acesso que você recebeu. Se ele expirou, solicite um novo.'}
form.onsubmit=async e=>{e.preventDefault();const password=document.getElementById('password').value;if(password!==document.getElementById('confirm').value){status.textContent='As senhas precisam ser iguais.';return}button.disabled=true;try{status.textContent='Criando seu acesso…';const r=await fetch(URL+'/functions/v1/activate-editor',{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json'},body:JSON.stringify({token,password})});const result=await r.json();if(!r.ok)throw Error(result.error||'Não foi possível criar o acesso.');history.replaceState(null,'',location.pathname);form.reset();form.hidden=true;status.textContent='Senha criada! Entrando no painel…';try{const s=await request('/auth/v1/token?grant_type=password',{method:'POST',body:{email:result.email,password}});saveSession(s);location.replace('/painel')}catch{status.textContent='Senha criada! Use seu e-mail e a nova senha para entrar pelo link do painel abaixo.'}}catch(e){status.textContent=e.message}finally{button.disabled=false}};
